def _sum(arr):
    """Return the sum of all elements in the array arr."""
    if not isinstance(arr, list) or any(not isinstance(item, (int, float)) for item in arr):
        raise ValueError("Input must be a non-empty list of numbers.")

    return sum(arr)
```

